<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, BookOpen, ChevronDown, CircleCheck, LogOut, PencilRuler, ShieldCheck } from '../components/icons'
import { api, session, setUsername, signOut } from '../services/api'
import type { Progress } from '../../shared/types'
import ChapterIcon from '../components/ChapterIcon.vue'

const router = useRouter()
const data = ref<Progress | null>(null)
const loading = ref(true)
const error = ref('')
const signingOut = ref(false)
const logoutError = ref('')
const usernameDraft = ref(session.user?.username || '')
const usernameBusy = ref(false)
const usernameError = ref('')
const usernameSaved = ref('')
const usernameChanged = computed(() => usernameDraft.value.trim().toLowerCase() !== (session.user?.username || ''))
watch(() => session.user?.username, username => { if (!usernameBusy.value) usernameDraft.value = username || '' })
const roleName = computed(() => session.user ? { student: 'Élève', contributor: 'Contributeur', admin: 'Administrateur' }[session.user.role] : '')
const canEdit = computed(() => session.user?.role === 'contributor' || session.user?.role === 'admin')
const initials = computed(() => (session.user?.name || '').trim().split(/\s+/).map(part => part[0]).slice(0, 2).join('').toUpperCase())
const days = computed(() => (data.value?.daily || []).map(day => ({ label: new Date(`${day.date}T12:00:00Z`).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', timeZone: 'Europe/Paris' }), count: day.answered })))
const activityPeak = computed(() => Math.max(1, ...days.value.map(day => day.count)))
const activityTotal = computed(() => days.value.reduce((total, day) => total + day.count, 0))
async function load() {
  loading.value = true
  error.value = ''
  try { data.value = await api<Progress>('/progress') }
  catch (cause) { error.value = (cause as Error).message }
  finally { loading.value = false }
}
function chapterStats(id: string) { return data.value?.chapters.find(chapter => chapter.chapterId === id) }
function chapterAccuracy(id: string) {
  const stats = chapterStats(id)
  return stats?.answered ? Math.round(stats.correct / stats.answered * 100) : 0
}
async function saveUsername() {
  if (usernameBusy.value || signingOut.value) return
  usernameError.value = ''
  usernameSaved.value = ''
  const username = usernameDraft.value.trim().toLowerCase()
  if (!/^[a-z0-9][a-z0-9._-]{2,23}$/.test(username)) {
    usernameError.value = 'Choisis un pseudo de 3 à 24 caractères : lettres sans accent, chiffres, point, tiret ou _. Commence par une lettre ou un chiffre.'
    return
  }
  usernameBusy.value = true
  try {
    await setUsername(username)
    usernameDraft.value = session.user?.username || username
    usernameSaved.value = 'Pseudo enregistré. Tu peux maintenant l’utiliser pour te connecter.'
  } catch (cause) { usernameError.value = (cause as Error).message }
  finally { usernameBusy.value = false }
}
async function logout() {
  if (signingOut.value) return
  signingOut.value = true
  logoutError.value = ''
  try { await signOut(); await router.replace({ name: 'login' }) }
  catch (cause) { logoutError.value = (cause as Error).message; if (!session.user) await router.replace({ name: 'login' }) }
  finally { signingOut.value = false }
}
onMounted(load)
</script>

<template>
  <div class="mobile-profile">
    <header class="screen-heading"><h1>Moi</h1></header>
    <section class="profile-identity" aria-label="Mon profil"><span class="profile-avatar" aria-hidden="true">{{ initials }}</span><div><h2>{{ session.user?.name }}</h2><span class="profile-role">{{ roleName }}</span><p v-if="session.user?.username" class="profile-username">@{{ session.user.username }}</p><p>{{ session.user?.email }}</p></div></section>
    <details class="username-settings" :open="!session.user?.username"><summary><span>{{ session.user?.username ? 'Modifier mon pseudo' : 'Choisir mon pseudo' }}</span><ChevronDown :size="19" /></summary><form class="username-form" :aria-busy="usernameBusy" @submit.prevent="saveUsername"><p>Utilise ton pseudo unique ou ton e-mail pour te connecter.</p><label for="profile-username">Pseudo</label><div class="username-form-row"><input id="profile-username" v-model="usernameDraft" name="username" type="text" autocomplete="username" autocapitalize="none" :spellcheck="false" minlength="3" maxlength="24" :disabled="usernameBusy || signingOut" aria-describedby="profile-username-help" required placeholder="camille.bcpst" @input="usernameError = ''; usernameSaved = ''"><button type="submit" :disabled="usernameBusy || signingOut || !usernameChanged">{{ usernameBusy ? 'Enregistrement…' : 'Enregistrer' }}</button></div><small id="profile-username-help">3 à 24 caractères : lettres sans accent, chiffres, point, tiret ou _. Commence par une lettre ou un chiffre.</small><p v-if="usernameError" class="username-error" role="alert">{{ usernameError }}</p><p v-if="usernameSaved" class="username-success" role="status">{{ usernameSaved }}</p></form></details>
    <nav v-if="canEdit" class="management-links" aria-label="Espace enseignant"><RouterLink to="/questions"><PencilRuler :size="20" /><span>Questions</span><ArrowRight :size="18" /></RouterLink><RouterLink v-if="session.user?.role === 'admin'" to="/admin"><ShieldCheck :size="20" /><span>Administration</span><ArrowRight :size="18" /></RouterLink></nav>
    <p v-if="loading" class="screen-state" role="status">Chargement de votre progression…</p>
    <div v-else-if="error" class="screen-state"><p class="error-copy" role="alert">{{ error }}</p><button class="secondary-action" @click="load">Réessayer</button></div>
    <template v-else-if="data">
      <section class="progress-summary" aria-labelledby="progress-title"><h2 id="progress-title">Mes révisions</h2><dl class="progress-numbers"><div><dt>Points</dt><dd>{{ data.totalPoints.toLocaleString('fr-FR') }}</dd></div><div><dt>Précision</dt><dd>{{ data.accuracy }}<small> %</small></dd></div><div><dt>Sessions terminées</dt><dd>{{ data.gamesPlayed }}</dd></div><div><dt>Réponses justes</dt><dd>{{ data.correct }}<small> / {{ data.answered }}</small></dd></div></dl><RouterLink to="/practice" class="review-action">Réviser en solo<ArrowRight :size="18" /></RouterLink></section>
      <div class="progress-details">
        <details class="profile-detail"><summary><span>Par chapitre</span><span class="detail-meta">{{ session.bootstrap?.chapters.length || 0 }} chapitres</span><ChevronDown :size="19" /></summary><div class="detail-content"><div v-for="chapter in session.bootstrap?.chapters" :key="chapter.id" class="mastery-row"><span class="chapter-icon"><ChapterIcon :id="chapter.id" :size="22" /></span><div><strong>{{ chapter.shortName }}</strong><p>{{ chapterStats(chapter.id)?.answered || 0 }} réponses · {{ chapterStats(chapter.id)?.points || 0 }} points</p><div class="mastery-track" role="progressbar" :aria-label="`Précision en ${chapter.name}`" :aria-valuenow="chapterAccuracy(chapter.id)" aria-valuemin="0" aria-valuemax="100"><span :style="{ width: `${chapterAccuracy(chapter.id)}%` }"></span></div></div><span class="mastery-percent">{{ chapterAccuracy(chapter.id) }} %</span></div></div></details>
        <details class="profile-detail"><summary><span>Activité</span><span class="detail-meta">{{ data.streak }} {{ data.streak > 1 ? 'jours' : 'jour' }} de suite</span><ChevronDown :size="19" /></summary><div class="detail-content"><p class="detail-intro">{{ activityTotal }} réponses ces 14 derniers jours.</p><div class="activity-chart" aria-label="Activité des 14 derniers jours"><div v-for="(day, index) in days" :key="day.label" class="activity-column" :aria-label="`${day.label} : ${day.count} réponses`"><div class="activity-bar"><span :class="{ inactive: !day.count }" :style="{ height: `${Math.max(4, day.count / activityPeak * 100)}%` }"></span></div><small :class="{ 'date-hidden': index !== 0 && index !== 6 && index !== days.length - 1 }">{{ day.label }}</small></div></div></div></details>
        <details class="profile-detail"><summary><span>Erreurs à revoir</span><span class="detail-meta">{{ data.mistakes.length }}</span><ChevronDown :size="19" /></summary><div class="detail-content"><div v-if="!data.mistakes.length" class="detail-empty"><CircleCheck :size="25" /><p>{{ data.answered ? 'Aucune erreur à revoir.' : 'Vos questions à retravailler apparaîtront après votre premier quiz.' }}</p></div><template v-else><RouterLink to="/practice?mistakes=1" class="secondary-action">Revoir mes erreurs<ArrowRight :size="18" /></RouterLink><ul class="mistake-list"><li v-for="mistake in data.mistakes" :key="mistake.questionId"><ChapterIcon :id="mistake.chapterId" :size="20" /><p>{{ mistake.prompt }}</p><span :aria-label="`${mistake.count} erreurs`">{{ mistake.count }}×</span></li></ul></template></div></details>
        <details class="profile-detail"><summary><span>Dernières sessions</span><span class="detail-meta">{{ data.recentGames.length }}</span><ChevronDown :size="19" /></summary><div class="detail-content history-content"><p v-if="!data.recentGames.length" class="detail-intro">Terminez un premier quiz pour retrouver ses résultats ici.</p><RouterLink v-for="game in data.recentGames" :key="game.id" :to="`/game/${game.id}`" class="session-row"><span class="session-icon"><BookOpen :size="20" /></span><div><strong>{{ game.mode === 'multi' ? 'Défi multijoueur' : 'Révision solo' }}</strong><time :datetime="game.createdAt">{{ new Date(game.createdAt).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Paris' }) }}</time><span>{{ game.correct }} / {{ game.total }} réponses justes</span></div><strong class="session-points">{{ game.score }}<small>points</small></strong><ArrowRight :size="17" /></RouterLink></div></details>
      </div>
    </template>
    <p v-if="logoutError" class="error-copy" role="alert">{{ logoutError }}</p>
    <button class="logout-action" :disabled="signingOut || usernameBusy" @click="logout"><LogOut :size="19" />{{ signingOut ? 'Déconnexion…' : 'Se déconnecter' }}</button>
  </div>
</template>

<style scoped>
