ght:75px}.activity-bar>span{display:block;width:100%;border-radius:4px 4px 0 0;background:#21664b}.activity-bar>span.inactive{background:#dfe8e2}.activity-column small{display:block;font-size:10px;white-space:nowrap;color:#647c6e;line-height:1.4;margin-top:9px}.activity-column:last-child small{text-align:right;position:relative;right:22px}.activity-column .date-hidden{visibility:hidden}.detail-empty{display:flex;align-items:flex-start;gap:12px;color:#21664b;padding:4px 0 2px}.detail-empty>svg{flex-shrink:0;margin-top:1px}.detail-empty p{font-size:14px;line-height:1.6;color:#52695c;margin:0}.mistake-list{list-style:none;margin:7px 0 0;padding:0}.mistake-list li{display:flex;align-items:flex-start;gap:11px;padding:16px 0;border-bottom:1px solid #e6ede8}.mistake-list li:last-child{border-bottom:0;padding-bottom:0}.mistake-list li>svg{flex-shrink:0;color:#21664b;margin-top:3px}.mistake-list p{flex:1;min-width:0;font-size:14px;line-height:1.6;margin:0}.mistake-list li>span{font-size:12px;color:#647c6e;margin-top:4px}.history-content{padding-top:0;padding-bottom:5px}.history-content>.detail-intro{margin-bottom:13px}.session-row{display:flex;align-items:center;gap:10px;min-height:88px;padding:15px 0;border-top:1px solid #e6ede8;color:#17382e;text-decoration:none}.session-icon{display:grid;place-items:center;flex:0 0 31px;height:36px;color:#21664b}.session-row>div{flex:1;min-width:0}.session-row>div strong{display:block;font-size:14px;font-weight:600;line-height:1.4}.session-row time,.session-row>div>span{display:block;font-size:12px;line-height:1.5;color:#647c6e;margin-top:3px}.session-points{font-size:16px;font-weight:700;text-align:right;font-variant-numeric:tabular-nums}.session-points small{display:block;font-size:11px;font-weight:400;color:#647c6e;margin-top:4px}.session-row>svg{flex-shrink:0;color:#647c6e}.logout-action{display:flex;align-items:center;justify-content:center;gap:11px;min-height:49px;padding:13px 17px;background:transparent;border:1px solid #d8e2dc;bor